  ('A3_SH01', $pp${"positivePrompt": "{STYLE}, {PALETTE_A3}, wide shot of Mogilev apartment kitchen with yellow floral wallpaper March 2019 morning, {HEROINE_ELENA_AGE_39} standing at kitchen table packing small black wheeled suitcase open on chair, folding dark navy blazer with Bronze Partner badge into suitcase, on table turquoise BIO+ document folder small bottle of perfume pack of business cards, weak overcast March daylight from window on right, hard ink outline cell-shaded color blocks two-tone, WS eye level locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Март две тысячи девятнадцать, ты собираешь сумку для двухдневной поездки в Гомель"}$pp$, 'WS', 'eye', 'static', 'rising', 'character', 'heroine_elena', FALSE, FALSE, 'spring_autumn_2019', 'A3_corporate_cold'),
